action.mutation:
mutation CreateAndonRequest($payload: [AndonRequestCreatePayloadInput!]!) {
  mutation: createAndonRequest(payload: $payload) { 
    id
    number
  }
}

mutation UpdateAndonRequest($payload: [AndonRequestUpdatePayloadInput!]!) {
  mutation: updateAndonRequest(payload: $payload) { 
    id
    number
  }
}

mutation DeleteAndonRequest($payload: [AndonRequestDeletePayloadInput!]!) {
  mutation: deleteAndonRequest(payload: $payload) { 
    id
    number
  }
}
